export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;
  const mass = inputs.mass;
  const t = time;

  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);
  const height = launchSpeed * t - 0.5 * gravity * t * T;
  const velocity = launchSpeed - gravity * t;
  const acceleration = -gravity;
  const force = mass * gravity;

  let motionState = "Rising";
  if (t === 0) motionState = "Ready to toss";
  else if (Math.abs(velocity) < 0.05) motionState = "At the top";
  else if (velocity < 0 && height > 0) motionState = "Falling";
  else if (height <= 0) motionState = "Back at launch height";

  const objects = [];

  // Lanes using sdk.panel
  objects.push(...sdk.panel({ x: 20, y: 40, w: 280, h: 350, title: "The Motion", state: motionState, id: "lane.motion" }));
  objects.push(...sdk.panel({ x: 320, y: 40, w: 300, h: 350, title: "Velocity over time", state: `t = ${sdk.format(t, 2)} s`, id: "lane.graph" }));

  // Left side: Height ruler & ball
  objects.push(sdk.axis("axis.height", { x: 50, y: 350, length: 260, orientation: "y", min: 0, max: 2.2, ticks: [0, 0.5, 1.0, 1.5, 2.0], label: "Height", unit: "m" }));
  const ballY = 350 - (height / 2.2) * 260;
  objects.push(sdk.circle("ball.toss", 120, ballY, 24, { role: "output" }));

  // Vectors for ball
  const vScale = 15;
  objects.push(...sdk.vector("vec.v", { x: 150, y: ballY }, { value: velocity, direction: "up" }, { scale: vScale, label: "v" }));
  objects.push(...sdk.vector("vec.a", { x: 180, y: ballY }, { value: acceleration, direction: "up" }, { scale: vScale, label: "a" }));

  // Callout for ball
  const calloutLines = [
    `v: ${sdk.format(velocity, 2)} m/s`,
    `a: ${sdk.format(acceleration, 2)} m/s^2`,
    `Fg: ${sdk.format(force, 2)} N`
  ];
  objects.push(...sdk.callout(210, ballY - 20, calloutLines, { id: "callout.toss" }));

  // Right side: v-t plot (sdk.plot with axes)
  const totalDuration = (2 * launchSpeed) / gravity;
  const points = sdk.sample((currT) => launchSpeed - gravity * currT, 0, totalDuration, 20);

  objects.push(sdk.plot("plot.vt", {
    x: 340,
    y: 80,
    w: 260,
    h: 220,
    axes: {
      x: { label: "Time", min: 0, max: Math.max(2.0, totalDuration), unit: "s" },
      y: { label: "Velocity", min: -6, max: 6, unit: "m/s" }
    },
    series: [
      { label: "v(t)", kind: "line", points: points.map(pt => ({ x: pt[0], y: Math.max(-5.5, Math.min(5.5, pt[1])) })) }
    ]
  }));

  objects.push(sdk.text("plot.vt.note", 340, 320, "Slope a = -g", { role: "neutral" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "velocity", value: velocity },
        { id: "acceleration", value: acceleration },
        { id: "force", value: force },
        { id: "motionState", value: motionState }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      mass,
      apexTime,
      apexHeight,
      height,
      velocity,
      acceleration,
      force
    }
  };
}
